  "l4-scene-iii-3": "/audio/books/dialogues/genki-1/l4-scene-iii-3.opus",
  "モスバーガーじゃないですよ。マクドナルドですよ。": "/audio/books/dialogues/genki-1/l4-scene-iii-3.opus",
  "/audio/books/dialogues/genki-1/l4-scene-iii-4.opus": "/audio/books/dialogues/genki-1/l4-scene-iii-4.opus",
