  "l21-scene-ii-8": "/audio/books/dialogues/mnn-1/l21-scene-ii-8.opus",
  "最近の子どもについてどう思いますか。": "/audio/books/dialogues/mnn-1/l21-scene-ii-8.opus",
  "/audio/books/dialogues/mnn-1/l21-scene-ii-9.opus": "/audio/books/dialogues/mnn-1/l21-scene-ii-9.opus",
