  "mnn-1:l21-scene-iii-4": "/audio/books/dialogues/mnn-1/l21-scene-iii-4.opus",
  "中で飲み物を売っていると言いました。": "/audio/books/dialogues/mnn-1/l21-scene-iii-4.opus",
  "/audio/books/dialogues/mnn-1/l21-scene-iii-5.opus": "/audio/books/dialogues/mnn-1/l21-scene-iii-5.opus",
