  "l21-scene-iii-7": "/audio/books/dialogues/mnn-1/l21-scene-iii-7.opus",
  "レストランは10時までだと言いました。": "/audio/books/dialogues/mnn-1/l21-scene-iii-7.opus",
  "/audio/books/dialogues/mnn-1/l21-scene-iii-8.opus": "/audio/books/dialogues/mnn-1/l21-scene-iii-8.opus",
