  "mnn-1:l22-scene-iii-4": "/audio/books/dialogues/mnn-1/l22-scene-iii-4.opus",
  "/audio/books/dialogues/mnn-1/l22-scene-iii-5.opus": "/audio/books/dialogues/mnn-1/l22-scene-iii-5.opus",
  "mnn-1:l22-scene-iii-5": "/audio/books/dialogues/mnn-1/l22-scene-iii-5.opus",
  "l22-scene-iii-5": "/audio/books/dialogues/mnn-1/l22-scene-iii-5.opus",
