  "l24-scene-iv-13": "/audio/books/dialogues/mnn-1/l24-scene-iv-13.opus",
  "お父さんは古いお寺へ連れて行ってくれました。": "/audio/books/dialogues/mnn-1/l24-scene-iv-13.opus",
  "/audio/books/dialogues/mnn-1/l24-scene-iv-14.opus": "/audio/books/dialogues/mnn-1/l24-scene-iv-14.opus",
