  "仙台の七夕祭りに行ったことがありますか。": "/audio/books/dialogues/mnn-2/l40-scene-iv-0.opus",
  "/audio/books/dialogues/mnn-2/l40-scene-iv-1.opus": "/audio/books/dialogues/mnn-2/l40-scene-iv-1.opus",
  "mnn-2:l40-scene-iv-1": "/audio/books/dialogues/mnn-2/l40-scene-iv-1.opus",
