  "/audio/books/dialogues/mnn-2/l41-scene-ii-3.opus": "/audio/books/dialogues/mnn-2/l41-scene-ii-3.opus",
  "mnn-2:l41-scene-ii-3": "/audio/books/dialogues/mnn-2/l41-scene-ii-3.opus",
  "l41-scene-ii-3": "/audio/books/dialogues/mnn-2/l41-scene-ii-3.opus",
  "日本語や 日本料理の 作り方を 教えて くださいました。": "/audio/books/dialogues/mnn-2/l41-scene-ii-3.opus",
  "/audio/books/dialogues/mnn-2/l41-scene-ii-4.opus": "/audio/books/dialogues/mnn-2/l41-scene-ii-4.opus",
  "mnn-2:l41-scene-ii-4": "/audio/books/dialogues/mnn-2/l41-scene-ii-4.opus",
  "l41-scene-ii-4": "/audio/books/dialogues/mnn-2/l41-scene-ii-4.opus",
  "それは よかったですね。": "/audio/books/dialogues/mnn-2/l41-scene-ii-4.opus",
