  "mnn-2:l41-scene-iv-3": "/audio/books/dialogues/mnn-2/l41-scene-iv-3.opus",
  "l41-scene-iv-3": "/audio/books/dialogues/mnn-2/l41-scene-iv-3.opus",
  "/audio/books/dialogues/mnn-2/l41-scene-iv-4.opus": "/audio/books/dialogues/mnn-2/l41-scene-iv-4.opus",
  "mnn-2:l41-scene-iv-4": "/audio/books/dialogues/mnn-2/l41-scene-iv-4.opus",
  "l41-scene-iv-4": "/audio/books/dialogues/mnn-2/l41-scene-iv-4.opus",
  "①棚を 組み立てたいです ②ドライバーを 貸します": "/audio/books/dialogues/mnn-2/l41-scene-iv-4.opus",
