  "mnn-2:l41-scene-iv-5": "/audio/books/dialogues/mnn-2/l41-scene-iv-5.opus",
  "l41-scene-iv-5": "/audio/books/dialogues/mnn-2/l41-scene-iv-5.opus",
  "①友達が 入院しました ②お見舞いは 何が いいか、教えます": "/audio/books/dialogues/mnn-2/l41-scene-iv-5.opus",
  "/audio/books/dialogues/mnn-2/l42-scene-i-0.opus": "/audio/books/dialogues/mnn-2/l42-scene-i-0.opus",
  "mnn-2:l42-scene-i-0": "/audio/books/dialogues/mnn-2/l42-scene-i-0.opus",
  "l42-scene-i-0": "/audio/books/dialogues/mnn-2/l42-scene-i-0.opus",
  "林さん、ボーナスはいつ出るんですか。": "/audio/books/dialogues/mnn-2/l42-scene-i-0.opus",
