  "mnn-2:l42-scene-i-1": "/audio/books/dialogues/mnn-2/l42-scene-i-1.opus",
  "l42-scene-i-1": "/audio/books/dialogues/mnn-2/l42-scene-i-1.opus",
  "来週です。鈴木さんの会社は？": "/audio/books/dialogues/mnn-2/l42-scene-i-1.opus",
