  "l4-scene-i-11": "/audio/books/dialogues/mnn-3/l4-scene-i-11.opus",
  "/audio/books/dialogues/mnn-3/l4-scene-i-12.opus": "/audio/books/dialogues/mnn-3/l4-scene-i-12.opus",
