  "/audio/books/dialogues/mnn-3/l9-scene-ii-0.opus": "/audio/books/dialogues/mnn-3/l9-scene-ii-0.opus",
  "mnn-3:l9-scene-ii-0": "/audio/books/dialogues/mnn-3/l9-scene-ii-0.opus",
  "この かばんは いかがでしょうか。とても 丈夫ですよ。": "/audio/books/dialogues/mnn-3/l9-scene-ii-0.opus",
  "/audio/books/dialogues/mnn-3/l9-scene-ii-1.opus": "/audio/books/dialogues/mnn-3/l9-scene-ii-1.opus",
