  "mnn-3:l10-scene-i-9": "/audio/books/dialogues/mnn-3/l10-scene-i-9.opus",
  "/audio/books/dialogues/mnn-3/l10-scene-i-10.opus": "/audio/books/dialogues/mnn-3/l10-scene-i-10.opus",
  "mnn-3:l10-scene-i-10": "/audio/books/dialogues/mnn-3/l10-scene-i-10.opus",
  "l10-scene-i-10": "/audio/books/dialogues/mnn-3/l10-scene-i-10.opus",
  "1週間前から ずっと 置いて ありますよ。": "/audio/books/dialogues/mnn-3/l10-scene-i-10.opus",
